def seed_ocean_locations(apps, schema_editor):
    OceanLocation = apps.get_model("explorer", "OceanLocation")
    Ecosystem = apps.get_model("explorer", "Ecosystem")

    for loc_data in SEED_LOCATIONS:
        ecosystems_list = loc_data["ecosystems"]
        location_fields = {k: v for k, v in loc_data.items() if k != "ecosystems"}

        # Chỉ tạo nếu chưa tồn tại slug này để không ghi đè dữ liệu do người dùng chỉnh sửa
        location_obj, _ = OceanLocation.objects.get_or_create(
            slug=location_fields["slug"],
            defaults=location_fields,
        )

        for eco_data in ecosystems_list:
            if not Ecosystem.objects.filter(slug=eco_data["slug"]).exists():
                Ecosystem.objects.create(location=location_obj, **eco_data)


def remove_seeded_ocean_locations(apps, schema_editor):
    OceanLocation = apps.get_model("explorer", "OceanLocation")
    Ecosystem = apps.get_model("explorer", "Ecosystem")

    seeded_eco_slugs = [
        eco["slug"]
        for loc in SEED_LOCATIONS
        for eco in loc["ecosystems"]
    ]
    seeded_loc_slugs = [loc["slug"] for loc in SEED_LOCATIONS]

    Ecosystem.objects.filter(slug__in=seeded_eco_slugs).delete()
    OceanLocation.objects.filter(slug__in=seeded_loc_slugs, ecosystems__isnull=True).delete()


class Migration(migrations.Migration):

    dependencies = [
        ("explorer", "0004_oceanlocation_ecosystem"),
    ]

    operations = [
        migrations.RunPython(seed_ocean_locations, reverse_code=remove_seeded_ocean_locations),
    ]

